// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type PitchPlotProps = Record<string, any>;

const PitchPlot: React.FC<PitchPlotProps> = ({
  backgroundColor = "#0a0c10",
  transparentBackground = true,
  durationInSeconds = 10,
  title = "PITCH MOVEMENT",
  titleFontFamily = "Inter",
  xAxisLabel = "HORZ BREAK (IN)",
  xAxisLabelFontFamily = "Inter",
  yAxisLabel = "INDUCED VERT BREAK (IN)",
  yAxisLabelFontFamily = "Inter",
  panelOpacity = 0.85,
  series1Label = "Curveball",
  series1LabelFontFamily = "Inter",
  series1Color = "#ffaa33",
  series2Label = "4-Seam",
  series2LabelFontFamily = "Inter",
  series2Color = "#ff4444",
  series3Label = "Slider",
  series3LabelFontFamily = "Inter",
  series3Color = "#bb44ff",
  pitches = [
    // Curveballs (Orange, Series 1)
    { series: "1", x: -12, y: -15 },
    { series: "1", x: -14, y: -10 },
    { series: "1", x: -10, y: -12 },
    { series: "1", x: -11, y: -9 },
    { series: "1", x: -7, y: -15 },
    { series: "1", x: -9, y: -11 },
    // 4-Seam (Red, Series 2)
    { series: "2", x: 2, y: 11 },
    { series: "2", x: 3, y: 14 },
    { series: "2", x: 5, y: 10 },
    { series: "2", x: 6, y: 9 },
    { series: "2", x: 7, y: 7 },
    { series: "2", x: 8, y: 12 },
    { series: "2", x: 4, y: 16 },
    { series: "2", x: 5, y: 18 },
    { series: "2", x: 7, y: 19 },
    { series: "2", x: 11, y: 14 },
    { series: "2", x: 12, y: 10 },
    { series: "2", x: 9, y: 17 },
    // Slider (Purple, Series 3)
    { series: "3", x: -10, y: 2 },
    { series: "3", x: -8, y: -1 },
    { series: "3", x: -9, y: -4 },
    { series: "3", x: -7, y: -3 },
    { series: "3", x: -5, y: 4 },
    { series: "3", x: -4, y: 2 },
    { series: "3", x: -3, y: -4 },
    { series: "3", x: -4, y: -5 },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout math optimized for 1:1 ratio
  const panelW = 900 * s;
  const panelH = 900 * s;
  const paddingX = 130 * s;
  const paddingY = 130 * s;
  const gw = panelW - paddingX * 2;
  const gh = panelH - paddingY * 2;

  // Domain & Mapping
  // X: -25 to 25
  // Y: -35 to 35
  const mapX = (val: number) => paddingX + ((val + 25) / 50) * gw;
  const mapY = (val: number) => paddingY + ((35 - val) / 70) * gh; // Inverted Y

  const xTicks = [-20, -10, 0, 10, 20];
  const yTicks = [-30, -20, -10, 0, 10, 20, 30];

  const zeroX = mapX(0);
  const zeroY = mapY(0);

  const getSeriesColor = (series: string) => {
    if (series === "1") return series1Color;
    if (series === "2") return series2Color;
    return series3Color;
  };

  // Animations - Entrance
  const panelEntrance = spring({
    frame: frame - 5,
    fps,
    config: { damping: 14, mass: 0.8 },
  });
  
  const panelOpacityVal = interpolate(frame, [5, 20], [0, panelOpacity], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const gridReveal = interpolate(frame, [20, 45], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const labelsOpacity = interpolate(frame, [35, 55], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const legendOpacity = interpolate(frame, [50, 70], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          width: panelW,
          height: panelH,
          backgroundColor: `rgba(10, 15, 25, ${panelOpacityVal})`,
          borderRadius: 24 * s,
          boxShadow: `0 0 ${30 * s}px rgba(100, 150, 255, ${panelOpacityVal * 0.3}), inset 0 0 ${40 * s}px rgba(100, 150, 255, ${panelOpacityVal * 0.1})`,
          border: `${2 * s}px solid rgba(255,255,255,0.15)`,
          position: "relative",
          transform: `scale(${interpolate(panelEntrance, [0, 1], [0.95, 1])})`,
          opacity: panelEntrance > 0 ? 1 : 0,
          transition: "none",
        }}
      >
        {/* Header Shape */}
        <div
          style={{
            position: "absolute",
            top: -30 * s,
            left: "50%",
            transform: "translateX(-50%)",
            width: 500 * s,
            height: 60 * s,
            opacity: interpolate(frame, [15, 30], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }),
            transition: "none",
          }}
        >
          <svg width="100%" height="100%" viewBox="0 0 500 60" preserveAspectRatio="none">
            <polygon
              points="40,0 460,0 500,60 0,60"
              fill="#0a0c10"
              stroke="rgba(255,255,255,0.3)"
              strokeWidth={2}
            />
            {/* Header Glow Flares */}
            <line x1="30" y1="0" x2="80" y2="0" stroke="#66aaff" strokeWidth="4" filter="blur(4px)" />
            <line x1="420" y1="0" x2="470" y2="0" stroke="#66aaff" strokeWidth="4" filter="blur(4px)" />
          </svg>
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              width: "100%",
              height: "100%",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              color: "white",
              fontSize: 28 * s,
              fontWeight: 800,
              letterSpacing: 2 * s,
              fontStyle: "italic",
              fontFamily: interFamily,
            }}
          >
            {title}
          </div>
        </div>

        {/* SVG Drawing Layer (Grid & Trails) */}
        <svg
          width={panelW}
          height={panelH}
          style={{ position: "absolute", top: 0, left: 0, transition: "none" }}
        >
          {/* Grid Lines */}
          <g opacity={gridReveal}>
            {xTicks.map((val) => {
              if (val === 0) return null; // Handle 0 separately
              const x = mapX(val);
              return (
                <line
                  key={`x-${val}`}
                  x1={x}
                  y1={paddingY}
                  x2={x}
                  y2={panelH - paddingY}
                  stroke="rgba(255, 255, 255, 0.15)"
                  strokeWidth={2 * s}
                  strokeDasharray={`${6 * s} ${6 * s}`}
                />
              );
            })}
            {yTicks.map((val) => {
              if (val === 0) return null;
              const y = mapY(val);
              return (
                <line
                  key={`y-${val}`}
                  x1={paddingX}
                  y1={y}
                  x2={panelW - paddingX}
                  y2={y}
                  stroke="rgba(255, 255, 255, 0.15)"
                  strokeWidth={2 * s}
                  strokeDasharray={`${6 * s} ${6 * s}`}
                />
              );
            })}

            {/* Zero Axes */}
            <line
              x1={zeroX}
              y1={paddingY}
              x2={zeroX}
              y2={panelH - paddingY}
              stroke="rgba(255, 70, 70, 0.6)"
              strokeWidth={3 * s}
              style={{ filter: `drop-shadow(0 0 ${4 * s}px rgba(255, 70, 70, 0.8))` }}
            />
            <line
              x1={paddingX}
              y1={zeroY}
              x2={panelW - paddingX}
              y2={zeroY}
              stroke="rgba(255, 70, 70, 0.6)"
              strokeWidth={3 * s}
              style={{ filter: `drop-shadow(0 0 ${4 * s}px rgba(255, 70, 70, 0.8))` }}
            />
          </g>

          {/* Pitch Trails & Dots */}
          {pitches.map((p, i) => {
            const startFrame = 45 + i * 2;
            const progress = spring({
              frame: frame - startFrame,
              fps,
              config: { damping: 12, mass: 0.8, stiffness: 100 },
            });

            if (progress === 0) return null;

            const targetX = mapX(p.x);
            const targetY = mapY(p.y);
            
            // Break animation from center (0,0) to target
            const currX = interpolate(progress, [0, 1], [zeroX, targetX]);
            const currY = interpolate(progress, [0, 1], [zeroY, targetY]);
            
            const color = getSeriesColor(p.series);
            const trailOpacity = interpolate(progress, [0, 0.7, 1], [0.8, 0.3, 0], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            });
            const scale = interpolate(progress, [0, 1], [0, 1], { extrapolateRight: "clamp" });

            return (
              <g key={`pitch-${i}`} style={{ transition: "none" }}>
                {/* Trail Line */}
                <line
                  x1={zeroX}
                  y1={zeroY}
                  x2={currX}
                  y2={currY}
                  stroke={color}
                  strokeWidth={4 * s}
                  strokeLinecap="round"
                  opacity={trailOpacity}
                  style={{ filter: `drop-shadow(0 0 ${6 * s}px ${color})` }}
                />
                {/* Pitch Marker */}
                <circle
                  cx={currX}
                  cy={currY}
                  r={8 * s * scale}
                  fill={color}
                  stroke="white"
                  strokeWidth={2.5 * s * scale}
                  style={{
                    filter: `drop-shadow(0 0 ${8 * s}px ${color}) drop-shadow(0 0 ${16 * s}px ${color})`,
                  }}
                />
              </g>
            );
          })}
        </svg>

        {/* Labels Layer (HTML for crisp text rendering) */}
        <div style={{ opacity: labelsOpacity, transition: "none", width: "100%", height: "100%", position: "absolute", top: 0, left: 0, pointerEvents: "none" }}>
          {/* Y Axis Labels */}
          {yTicks.map((val) => (
            <div
              key={`y-label-${val}`}
              style={{
                position: "absolute",
                left: paddingX - 20 * s,
                top: mapY(val),
                transform: "translate(-100%, -50%)",
                color: "white",
                fontSize: 20 * s,
                fontWeight: 700,
                fontFamily: interFamily,
                textShadow: `0 2px ${4 * s}px rgba(0,0,0,0.8)`,
              }}
            >
              {val}
            </div>
          ))}
          {/* Y Axis Title */}
          <div
            style={{
              position: "absolute",
              left: 40 * s,
              top: panelH / 2,
              transform: "translate(-50%, -50%) rotate(-90deg)",
              color: "white",
              fontSize: 22 * s,
              fontWeight: 800,
              fontFamily: interFamily,
              letterSpacing: 1.5 * s,
              whiteSpace: "nowrap",
            }}
          >
            {yAxisLabel}
          </div>

          {/* X Axis Labels */}
          {xTicks.map((val) => (
            <div
              key={`x-label-${val}`}
              style={{
                position: "absolute",
                left: mapX(val),
                top: panelH - paddingY + 20 * s,
                transform: "translateX(-50%)",
                color: "white",
                fontSize: 20 * s,
                fontWeight: 700,
                fontFamily: interFamily,
                textShadow: `0 2px ${4 * s}px rgba(0,0,0,0.8)`,
              }}
            >
              {val}
            </div>
          ))}
          {/* X Axis Title */}
          <div
            style={{
              position: "absolute",
              left: panelW / 2,
              top: panelH - 50 * s,
              transform: "translateX(-50%)",
              color: "white",
              fontSize: 22 * s,
              fontWeight: 800,
              fontFamily: interFamily,
              letterSpacing: 1.5 * s,
            }}
          >
            {xAxisLabel}
          </div>
        </div>

        {/* Legend */}
        <div
          style={{
            position: "absolute",
            bottom: -60 * s,
            left: "50%",
            transform: "translateX(-50%)",
            display: "flex",
            gap: 40 * s,
            opacity: legendOpacity,
            transition: "none",
          }}
        >
          {[
            { label: series1Label, color: series1Color },
            { label: series2Label, color: series2Color },
            { label: series3Label, color: series3Color },
          ].map((item, idx) => (
            <div key={`legend-${idx}`} style={{ display: "flex", alignItems: "center", gap: 12 * s }}>
              <div
                style={{
                  width: 24 * s,
                  height: 24 * s,
                  borderRadius: "50%",
                  backgroundColor: item.color,
                  border: `${3 * s}px solid white`,
                  boxShadow: `0 0 ${12 * s}px ${item.color}`,
                }}
              />
              <span
                style={{
                  color: "white",
                  fontSize: 20 * s,
                  fontWeight: 700,
                  fontFamily: interFamily,
                  letterSpacing: 1 * s,
                  textShadow: `0 2px ${4 * s}px rgba(0,0,0,0.8)`,
                }}
              >
                {item.label.toUpperCase()}
              </span>
            </div>
          ))}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default PitchPlot;